<template>
  <SuperAdminLayout>
    <main class="sms-format">
      <header><div><h1>SMS Notification Format</h1><p>Example SMS template for customer system admins</p></div><div class="actions"><RouterLink to="/super-admin/notifications">←&nbsp; Back</RouterLink><button @click="save(true)">▣&nbsp; Save Draft</button><button @click="previewing=!previewing">◉&nbsp; Preview SMS</button><button @click="save(false)">✉&nbsp; Send SMS</button></div></header>
      <section class="panel info"><h2>A. Notification Information</h2><label>Notification No.<input :value="notificationNo" readonly></label><label>Notification Type<select v-model="form.type"><option>Payment Reminder</option><option>Account Verification</option><option>System Update</option><option>Security Alert</option></select></label><label>Priority<select v-model="form.priority"><option>High</option><option>Normal</option><option>Urgent</option></select></label><label>Method<input value="SMS" readonly></label><label>Status<input :value="notice||'Draft'" readonly></label></section>
      <div class="layout"><div><section class="panel"><h2>B. Send To</h2><div class="choices"><label><input v-model="scope" value="one" type="radio"> One Customer</label><label><input v-model="scope" value="selected" type="radio"> Selected Customers</label><label><input v-model="scope" value="all" type="radio"> All Customers</label></div><div class="fields"><label>Customer<select v-model="form.user_id"><option value="">Select customer</option><option v-for="customer in customers" :key="customer.id" :value="customer.id">{{customer.company_name||customer.name}}</option></select></label><label>Mobile Number<input v-model="form.recipient" placeholder="98765 43210"></label><label>Country Code<select v-model="country"><option>+65</option><option>+1</option><option>+880</option></select></label></div></section><section class="panel"><h2>C. SMS Details</h2><div class="fields two"><label>SMS Category<select v-model="form.type"><option>Payment Reminder</option><option>Account Verification</option><option>System Update</option><option>Security Alert</option></select></label><label>Required Action<select><option>Make Payment</option><option>Review Account</option><option>Contact Support</option></select></label></div><label>SMS Message<textarea v-model="message" maxlength="320" placeholder="Write the SMS message…"></textarea><small>{{message.length}} / 320 characters</small></label></section><div class="two-panels"><section class="panel"><h2>D. Sending Options</h2><label><input v-model="sendMode" value="now" type="radio"> Send Now</label><label><input v-model="sendMode" value="later" type="radio"> Schedule for Later</label><div class="fields two"><label>Scheduled Date<input v-model="scheduleDate" type="date"></label><label>Scheduled Time<input v-model="scheduleTime" type="time"></label></div></section><section class="panel"><h2>E. Recurring Options</h2><label><input v-model="recurring" type="checkbox"> Recurring Notification</label><div class="fields two"><label>Recurring Type<select v-model="recurringType"><option>Weekly</option><option>Monthly</option></select></label><label>Repeat Every<input v-model="repeatEvery" type="number" min="1"></label></div></section></div><section class="panel"><h2>F. Review and Approval</h2><div class="fields two"><label>Approved By<input placeholder="Select approver"></label><label>Internal Notes<textarea v-model="notes" placeholder="Enter internal notes (optional)"></textarea></label></div></section></div><aside class="panel phone"><h2>SMS Preview</h2><div class="phone-shell"><div class="phone-top">9:41</div><div class="contact">Super Admin<br><small>{{country}} {{form.recipient||'98765 43210'}}</small></div><p>{{message||'Your SMS message preview will appear here.'}}</p><div class="compose">Text Message <b>↑</b></div></div><p v-if="previewing" class="preview-note">Preview updated.</p></aside></div>
    </main>
  </SuperAdminLayout>
</template>
<script setup>import{onMounted,reactive,ref}from'vue';import{RouterLink}from'vue-router';import SuperAdminLayout from'../components/SuperAdminLayout.vue';import client from'../api/client';const customers=ref([]),scope=ref('one'),country=ref('+65'),sendMode=ref('now'),recurring=ref(false),recurringType=ref('Weekly'),repeatEvery=ref(1),scheduleDate=ref(''),scheduleTime=ref(''),notes=ref(''),previewing=ref(false),notice=ref(''),notificationNo='NTF-'+String(Date.now()).slice(-8),message=ref('Hello, reminder from Super Admin: your upcoming payment is due. Please complete payment on time to avoid service interruption. For help, contact Support.'),form=reactive({user_id:'',recipient:'',type:'Payment Reminder',priority:'High'});async function save(draft){if(!draft&&!form.recipient){notice.value='Enter a mobile number first';return}await client.post('/super-admin/notifications',{...form,channel:'sms',subject:message.value,recurring:recurring.value?recurringType.value:'One-time',schedule_for:sendMode.value==='later'&&scheduleDate.value?`${scheduleDate.value} ${scheduleTime.value||'09:00'}`:null});notice.value=draft?'Draft saved':'SMS sent';}onMounted(async()=>{customers.value=(await client.get('/super-admin/customers')).data.data.data||[]})</script>
<style scoped>.sms-format{color:#071d63}.sms-format header{display:flex;justify-content:space-between;gap:16px;margin-bottom:17px}.sms-format h1{font-size:2rem;margin:0}.sms-format header p{margin:4px 0;color:#607093}.actions{display:flex;gap:10px;flex-wrap:wrap}.actions a,.actions button{height:48px;display:inline-flex;align-items:center;box-sizing:border-box;border:1px solid #b9cbef;border-radius:5px;background:#fff;color:#0755dc;padding:0 18px;font-weight:700;text-decoration:none}.actions button:last-child{background:#0755dc;color:#fff}.panel{border:1px solid #dce5f3;border-radius:8px;background:#fff;padding:14px;margin-bottom:12px}.panel h2{margin:0 0 12px;color:#0755dc;font-size:1rem}.info{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}.info h2{grid-column:1/-1;margin-bottom:0}label{display:grid;gap:6px;font-size:.73rem;font-weight:800}input,select,textarea{width:100%;box-sizing:border-box;border:1px solid #cad8ed;border-radius:5px;background:#fff;color:#0b2160;padding:9px;font:inherit}textarea{min-height:92px;resize:vertical}small{color:#667694;font-weight:600}.layout{display:grid;grid-template-columns:3fr 1fr;gap:12px}.choices{display:flex;gap:28px;margin-bottom:16px;font-size:.8rem}.choices label,.panel>label{display:inline-flex}.fields{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.fields.two,.two-panels{grid-template-columns:repeat(2,1fr)}.two-panels{display:grid;gap:12px}.phone{margin:0}.phone-shell{max-width:280px;min-height:500px;margin:auto;border:8px solid #111;border-radius:35px;padding:14px;background:#fff;box-shadow:inset 0 0 0 1px #bbb}.phone-top{font-weight:800}.contact{text-align:center;margin:30px 0 50px}.phone-shell p{padding:13px;border-radius:17px;background:#eff1f5;color:#111;line-height:1.4}.compose{margin-top:145px;border:1px solid #ddd;border-radius:16px;padding:8px;color:#9aa3b5}.compose b{float:right;border-radius:50%;background:#24b657;color:white;padding:0 5px}.preview-note{text-align:center;color:#078338}@media(max-width:1000px){.layout{grid-template-columns:1fr}.phone{max-width:450px}.info{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.sms-format header{display:block}.actions{margin-top:12px}.info,.fields,.fields.two,.two-panels{grid-template-columns:1fr}.choices{display:grid;gap:8px}}</style>
